const texto = $input.first().json.content.parts[0].text;
const datos = JSON.parse(texto);
const webhook = $('Webhook1').first().json.body;
const vacante = webhook.vacante;
const experiencia = webhook.experiencia;
const formaciones = datos.formaciones || [];

const niveles = [
  { palabras: ['doctorado'], prioridad: 6 },
  { palabras: ['maestría', 'maestria', 'master'], prioridad: 5 },
  { palabras: ['universitario', 'universidad', 'pregrado', 'licenciatura'], prioridad: 4 },
  { palabras: ['tecnología', 'tecnologia', 'tecnólogo', 'tecnologo'], prioridad: 3 },
  { palabras: ['técnico', 'tecnico'], prioridad: 2 },
  { palabras: ['bachillerato', 'bachiller'], prioridad: 1 }
];

let nivelEducativo = 'No especificado';
let prioridadMayor = 0;

for (const formacion of formaciones) {
  const textoFormacion = String(formacion.titulo || '').toLowerCase();
  for (const nivel of niveles) {
    const encontrado = nivel.palabras.some(palabra => textoFormacion.includes(palabra));
    if (encontrado && nivel.prioridad > prioridadMayor) {
      nivelEducativo = formacion.titulo;
      prioridadMayor = nivel.prioridad;
    }
  }
}

const idCandidato = 'TF-' + $now.toFormat('yyyyMMddHHmmss') + '-' + Math.floor(Math.random() * 10000);

return [{
  json: {
    ID_candidato: idCandidato,
    ...datos,
    nivel_Educativo: nivelEducativo,
    vacante: vacante,
    experiencia: experiencia
  }
}];

const candidato = $('Code in JavaScript1').first().json;
const filas = $input.all().map(item => item.json);

const vacanteSeleccionada = String(candidato.vacante || '').trim().toLowerCase();

const vacanteEncontrada = filas.find(fila =>
  String(fila.titulo || '').trim().toLowerCase() === vacanteSeleccionada
);

if (!vacanteEncontrada) {
  throw new Error(`No se encontró la vacante: ${candidato.vacante}`);
}

const requisitos = String(vacanteEncontrada.hab_requeridas || '')
  .split(',')
  .map(h => h.trim())
  .filter(Boolean);

const experienciaMinima = Number(vacanteEncontrada.year_experiencia || 0);

return [{
  json: {
    ...candidato,
    vacante_ref: vacanteEncontrada.titulo,
    req_habilidades: requisitos,
    exp_minima: experienciaMinima
  }
}];

const item = $input.first().json;

const habilidades = Array.isArray(item.habilidades)
  ? item.habilidades
  : String(item.habilidades || '').split(',').map(h => h.trim()).filter(Boolean);

const experiencia = Number(item.experiencia || 0);
const requisitos = Array.isArray(item.req_habilidades) ? item.req_habilidades : [];
const expMinima = Number(item.exp_minima || 0);

const normalizar = texto => String(texto).trim().toLowerCase();

const habilidadesNormalizadas = habilidades.map(normalizar);
const requisitosNormalizados = requisitos.map(normalizar);

const habilidadesCoincidentes = requisitosNormalizados.filter(req =>
  habilidadesNormalizadas.some(habilidad => habilidad === req)
);

let porcentajeHabilidades = 0;

if (requisitosNormalizados.length > 0) {
  porcentajeHabilidades = habilidadesCoincidentes.length / requisitosNormalizados.length;
}

const puntosHabilidades = porcentajeHabilidades * 70;
const puntosExperiencia = experiencia >= expMinima ? 30 : 0;
const score = Math.round(puntosHabilidades + puntosExperiencia);

let clasificacion;

if (score >= 80) {
  clasificacion = 'Alta';
} else if (score >= 60) {
  clasificacion = 'Media';
} else {
  clasificacion = 'Baja';
}

return [{
  json: {
    ...item,
    habilidades_coincidentes: habilidadesCoincidentes,
    total_requisitos: requisitosNormalizados.length,
    requisitos_cumplidos: habilidadesCoincidentes.length,
    puntos_habilidades: Math.round(puntosHabilidades),
    puntos_experiencia: puntosExperiencia,
    score: score,
    clasificacion: clasificacion
  }
}];
